pub fn simple_nested(a: &mut Vec<i32>, b: &Vec<i32>, N: i32) -> i32 {
    // Convert N to usize for indexing
    let n = N as usize;

    // Optionally, you can assert that the lengths match the provided N:
    // debug_assert_eq!(a.len(), n);
    // debug_assert_eq!(b.len(), n);

    let mut sum = 0;
    for i in 0..n {
        // If b[i] == i then write 1, otherwise write 2
        let v = if b[i] == i as i32 { 1 } else { 2 };
        a[i] = v;
        sum += v;
    }
    sum
}

