        let mut a = vec![0; 5];
        let b = (0..5).map(|i| i as i32).collect::<Vec<i32>>();
        // b = [0,1,2,3,4] → all b[i] == i → all a[i] = 1 → sum = 5
        assert_eq!(simple_nested(&mut a, &b, 5), 5);
